    # Expands 4-byte LE values into an Array<Integer>. Does not use `unpack`
    # (`unpack("l<*")` mallocs 6 times per 256 bytes). Once, at start-up.
    def self.expand_i32(s)
      n = s.bytesize / 4
      a = Array.new(n, 0)
      i = 0
      while i < n
        o = i * 4
        v = s.getbyte(o) | (s.getbyte(o + 1) << 8) |
            (s.getbyte(o + 2) << 16) | (s.getbyte(o + 3) << 24)
        a[i] = v >= 0x80000000 ? v - 0x100000000 : v
        i += 1
      end
      a
    end

    def self.expand_u32(s)
      n = s.bytesize / 4
      a = Array.new(n, 0)
      i = 0
      while i < n
        o = i * 4
        a[i] = s.getbyte(o) | (s.getbyte(o + 1) << 8) |
               (s.getbyte(o + 2) << 16) | (s.getbyte(o + 3) << 24)
        i += 1
      end
      a
    end

